const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
document.addEventListener('DOMContentLoaded',()=>{mountChrome();document.body.classList.remove('loading');const h=$('.site-header'),t=$('.menu-toggle'),p=$('.scroll-progress');const onScroll=()=>{h?.classList.toggle('scrolled',scrollY>18);if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=`${max?scrollY/max*100:0}%`}};addEventListener('scroll',onScroll,{passive:true});onScroll();t?.addEventListener('click',()=>{const open=h.classList.toggle('open');t.setAttribute('aria-expanded',String(open))});$$('.nav a').forEach(a=>a.addEventListener('click',()=>h?.classList.remove('open')));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(el=>io.observe(el));loadSettings();initField()});
function mountChrome(){const page=document.body.dataset.page||'';const links=[['home','index.html','HOME'],['about','about.html','ABOUT'],['news','news.html','NEWS'],['members','members.html','MEMBERS'],['sponsors','sponsors.html','SPONSORS'],['contact','contact.html','CONTACT'],['shop','shop.html','SHOP']];const header=`<header class="site-header"><div class="scroll-progress"></div><div class="container header-inner"><a class="brand" href="index.html" aria-label="Realize Summit ホーム"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><button class="menu-toggle" aria-label="メニューを開く" aria-expanded="false"><span></span><span></span></button><nav class="nav" aria-label="メインナビゲーション">${links.map(([id,href,label])=>`<a href="${href}" ${page===id?'aria-current="page"':''} class="${id==='shop'?'shop-link':''}">${label}</a>`).join('')}</nav></div></header>`;const footer=`<footer class="site-footer"><div class="container"><div class="footer-main"><a class="brand" href="index.html"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><nav class="footer-links">${links.map(([,h,l])=>`<a href="${h}">${l}</a>`).join('')}</nav><div class="social-links"><a data-setting="x" href="#">X</a><a data-setting="youtube" href="#">YOUTUBE</a><a data-setting="twitch" href="#">TWITCH</a><a data-setting="discord" href="#">DISCORD</a></div></div><div class="copyright"><span>© 2026 REALIZE SUMMIT.</span><span>ALL RIGHTS RESERVED.</span></div></div></footer>`;$('#site-header')?.replaceWith(document.createRange().createContextualFragment(header));$('#site-footer')?.replaceWith(document.createRange().createContextualFragment(footer))}
async function loadSettings(){try{const s=await fetch('data/settings.json').then(r=>r.json());$$('[data-setting]').forEach(el=>{const k=el.dataset.setting;if(s[k]){if(el.tagName==='A')el.href=s[k];else el.textContent=s[k]}})}catch{}}
function initField(){const c=$('#hero-canvas');if(!c||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const x=c.getContext('2d'),mobile=innerWidth<700;let w,h,raf,px=.5,py=.5;const pts=Array.from({length:mobile?18:42},()=>({x:Math.random(),y:Math.random(),v:(Math.random()-.5)*.00018}));function resize(){w=c.width=innerWidth*devicePixelRatio;h=c.height=c.clientHeight*devicePixelRatio}function draw(){x.clearRect(0,0,w,h);x.strokeStyle='rgba(255,255,255,.065)';x.lineWidth=1*devicePixelRatio;const step=72*devicePixelRatio,ox=(px-.5)*18*devicePixelRatio,oy=(py-.5)*18*devicePixelRatio;for(let i=ox%step;i<w;i+=step){x.beginPath();x.moveTo(i,0);x.lineTo(i,h);x.stroke()}for(let i=oy%step;i<h;i+=step){x.beginPath();x.moveTo(0,i);x.lineTo(w,i);x.stroke()}x.fillStyle='rgba(255,106,0,.5)';pts.forEach(p=>{p.y=(p.y+p.v+1)%1;x.fillRect(p.x*w,p.y*h,1.4*devicePixelRatio,1.4*devicePixelRatio)});raf=requestAnimationFrame(draw)}addEventListener('resize',resize);addEventListener('pointermove',e=>{px=e.clientX/innerWidth;py=e.clientY/innerHeight},{passive:true});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(raf);if(!document.hidden)draw()});resize();draw()}
